#include <unistd.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>

/* Prepare pipe to have PIPE_BUF_FLAG_CAN_MERGE set on all slots */
static void prepare_pipe(int p[2]) {
    if (pipe(p)) {
        perror("pipe");
        exit(1);
    }

    /* Repeatedly write/read to set the PIPE_BUF_FLAG_CAN_MERGE flag */
    const unsigned pipe_size = fcntl(p[1], F_GETPIPE_SZ);
    static char buffer[4096];

    /* Write to fill the pipe */
    for (unsigned r = pipe_size; r > 0;) {
        unsigned n = r < sizeof(buffer) ? r : sizeof(buffer);
        write(p[1], buffer, n);
        r -= n;
    }
    /* Read it all out */
    for (unsigned r = pipe_size; r > 0;) {
        unsigned n = r < sizeof(buffer) ? r : sizeof(buffer);
        read(p[0], buffer, n);
        r -= n;
    }
}

