        close(fd);
        return -1;
    }

    int p[2];
    prepare_pipe(p);

    /* splice from position 0..offset into the pipe - this loads page into page cache 
     * and sets up the merge condition */
    loff_t off = 0;
    ssize_t nbytes = splice(fd, &off, p[1], NULL, offset, 0);
    if (nbytes < 0) {
        perror("splice");
        close(fd);
        close(p[0]);
